#!/usr/bin/env bash
# Resident NeoForge reference environment for the official Mekanism build. It lets any future work compare NBT, save
# data, config and behaviour against the upstream mod instead of re-downloading and re-installing a server.
#
# Lives outside the repository (~/.cache/mekanism-neoforge-reference) because it is ~200MB of upstream artifacts and
# must never be committed. The sample world inside it was generated by the official mod itself (see W-65 evidence).
#
# Usage: scripts/neoforge-reference.sh [status|start|stop|logs|install]
#   status    report pid, port, readiness and the mod jar identity (default; leaves nothing running)
#   start     launch the server in the background on demand; stop it when the comparison is done
#   stop      stop the running server gracefully
#   status    report pid, port, readiness and the mod jar identity
#   install   (re)install the NeoForge server files from the maven installer
#   logs      tail the reference server log
set -uo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
ENV_DIR=${MEKANISM_NEOFORGE_ENV:-$HOME/.cache/mekanism-neoforge-reference}
SERVER_DIR=$ENV_DIR/server
PORT=${MEKANISM_NEOFORGE_PORT:-25594}
PID_FILE=$ENV_DIR/server.pid
LOG_FILE=$ENV_DIR/server.log
NEOFORGE_VERSION=21.1.200
MEKANISM_JAR=Mekanism-1.21.1-10.7.19.85.jar
MEKANISM_SHA=004dbc9f3106f4d192aeaa1ee1190dd16ec9ca8059ed3d093b80034f4c574f43

fail() {
  printf 'neoforge-reference: %s\n' "$1" >&2
  exit 1
}

install_env() {
  mkdir -p "$SERVER_DIR/mods"
  if [[ ! -f $SERVER_DIR/run.sh ]]; then
    local installer=$ENV_DIR/installer.jar
    [[ -f $installer ]] || curl -fsSL --max-time 180 -o "$installer" \
      "https://maven.neoforged.net/releases/net/neoforged/neoforge/$NEOFORGE_VERSION/neoforge-$NEOFORGE_VERSION-installer.jar" ||
      fail 'could not download the NeoForge installer'
    ( cd "$SERVER_DIR" && java -jar "$installer" --installServer > "$ENV_DIR/install.log" 2>&1 ) ||
      fail 'NeoForge server install failed (see install.log)'
  fi
  if [[ ! -f $SERVER_DIR/mods/$MEKANISM_JAR ]]; then
    curl -fsSL --max-time 300 -o "$SERVER_DIR/mods/$MEKANISM_JAR" \
      "https://cdn.modrinth.com/data/Ce6I4WUE/versions/5KzzycBT/$MEKANISM_JAR" || fail 'could not download the official Mekanism jar'
  fi
  local actual
  actual=$(sha256sum "$SERVER_DIR/mods/$MEKANISM_JAR" | cut -d' ' -f1)
  [[ $actual == "$MEKANISM_SHA" ]] || fail "official Mekanism jar checksum mismatch: $actual"
  printf 'eula=true\n' > "$SERVER_DIR/eula.txt"
  printf 'online-mode=false\nserver-ip=127.0.0.1\nserver-port=%s\nmax-players=4\nlevel-name=world\nspawn-protection=0\nmotd=mekanism neoforge reference\n' \
    "$PORT" > "$SERVER_DIR/server.properties"
}

server_pid() {
  [[ -f $PID_FILE ]] || return 1
  local pid
  pid=$(cat "$PID_FILE")
  kill -0 "$pid" 2>/dev/null || return 1
  printf '%s' "$pid"
}

start_server() {
  if pid=$(server_pid); then
    printf 'neoforge-reference: already running (pid %s, port %s)\n' "$pid" "$PORT"
    return 0
  fi
  [[ -f $SERVER_DIR/run.sh ]] || install_env
  ( cd "$SERVER_DIR" && exec setsid bash -c "./run.sh nogui >> '$LOG_FILE' 2>&1" ) &
  printf '%s\n' "$!" > "$PID_FILE"
  local deadline=$((SECONDS + 180))
  while (( SECONDS < deadline )); do
    "$ROOT/scripts/wait-for-log-line.sh" -q -t 20 -p "$(cat "$PID_FILE")" --fail-on 'Failed to start' 'Done \(' "$LOG_FILE" >/dev/null
    case $? in
      0) printf 'neoforge-reference: started (pid %s, port %s)\n' "$(cat "$PID_FILE")" "$PORT"; return 0 ;;
      4|5) fail 'the reference server exited while starting (see logs)' ;;
    esac
  done
  fail 'the reference server was not ready within 180s'
}

stop_server() {
  if pid=$(server_pid); then
    kill "$pid" 2>/dev/null
    for _ in $(seq 1 30); do kill -0 "$pid" 2>/dev/null || break; sleep 1; done
    kill -9 "$pid" 2>/dev/null
    printf 'neoforge-reference: stopped (pid %s)\n' "$pid"
  else
    printf 'neoforge-reference: not running\n'
  fi
  rm -f "$PID_FILE"
}

case ${1:-status} in
  start) start_server ;;
  stop) stop_server ;;
  status)
    if pid=$(server_pid); then
      printf 'running pid=%s port=%s env=%s\n' "$pid" "$PORT" "$ENV_DIR"
      grep -F 'Done (' "$LOG_FILE" | tail -n 1
      grep -F 'Mekanism' "$LOG_FILE" | grep -E 'Loading|Done' | tail -n 1 || true
    else
      printf 'stopped env=%s port=%s\n' "$ENV_DIR" "$PORT"
    fi
    ;;
  install) install_env && printf 'neoforge-reference: installed in %s\n' "$ENV_DIR" ;;
  logs) tail -n 40 "$LOG_FILE" ;;
  *) fail "unknown action: $1" ;;
esac
